CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '');
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id); RETURN NEW; END $$;
CREATE TRIGGER create_sds_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text NOT NULL DEFAULT '', image text NOT NULL DEFAULT '', position integer NOT NULL DEFAULT 0, visible boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.categories TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_categories ON public.categories FOR SELECT TO anon,authenticated USING(visible);
CREATE POLICY admin_categories ON public.categories FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.works (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, description text NOT NULL DEFAULT '', category_id uuid REFERENCES public.categories(id) ON DELETE SET NULL, images jsonb NOT NULL DEFAULT '[]', specifications text NOT NULL DEFAULT '', material text NOT NULL DEFAULT '', video text NOT NULL DEFAULT '', published boolean NOT NULL DEFAULT false, featured boolean NOT NULL DEFAULT false, example boolean NOT NULL DEFAULT false, position integer NOT NULL DEFAULT 0, seo_title text NOT NULL DEFAULT '', seo_description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.works TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.works TO authenticated; GRANT ALL ON public.works TO service_role;
ALTER TABLE public.works ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_works ON public.works FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY admin_works ON public.works FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text NOT NULL DEFAULT '', details text NOT NULL DEFAULT '', image text NOT NULL DEFAULT '', published boolean NOT NULL DEFAULT false, example boolean NOT NULL DEFAULT false, position integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.services TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.services TO authenticated; GRANT ALL ON public.services TO service_role;
ALTER TABLE public.services ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_services ON public.services FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY admin_services ON public.services FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.site_settings (id text PRIMARY KEY DEFAULT 'main', content jsonb NOT NULL DEFAULT '{}');
GRANT SELECT ON public.site_settings TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.site_settings TO authenticated; GRANT ALL ON public.site_settings TO service_role;
ALTER TABLE public.site_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_settings ON public.site_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY admin_settings ON public.site_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.contact_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), name text NOT NULL, email text NOT NULL, phone text NOT NULL DEFAULT '', service text NOT NULL DEFAULT '', message text NOT NULL, reference text NOT NULL DEFAULT '', attachments jsonb NOT NULL DEFAULT '[]', consent boolean NOT NULL CHECK(consent), status text NOT NULL DEFAULT 'Novo' CHECK(status IN ('Novo','Em análise','Respondido','Concluído')), notes text NOT NULL DEFAULT '');
GRANT SELECT,UPDATE,DELETE ON public.contact_submissions TO authenticated; GRANT ALL ON public.contact_submissions TO service_role;
ALTER TABLE public.contact_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_submissions ON public.contact_submissions FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.contact_limits (key text PRIMARY KEY, last_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.contact_limits TO service_role;
ALTER TABLE public.contact_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.claim_contact_slot(address text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE claimed text; BEGIN INSERT INTO public.contact_limits(key) VALUES(address) ON CONFLICT(key) DO UPDATE SET last_at=now() WHERE contact_limits.last_at<now()-interval '1 minute' RETURNING key INTO claimed; RETURN claimed IS NOT NULL; END $$;
REVOKE ALL ON FUNCTION public.claim_contact_slot(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_contact_slot(text) TO service_role;
CREATE TABLE public.media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, path text NOT NULL UNIQUE, alt text NOT NULL DEFAULT '', folder text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.media TO authenticated; GRANT ALL ON public.media TO service_role;
ALTER TABLE public.media ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_media ON public.media FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
