INSERT INTO public.works(slug,name,description,category_id,images,published,featured,example,position,material) VALUES ('vaso-spiral','Vaso Spiral','Estudo de uma forma paramétrica, onde a geometria encontra a expressão. Conteúdo de demonstração; não representa um trabalho real da SDS3D.','11111111-1111-4111-8111-111111111111','["example:spiral"]',true,true,true,0,'Exemplo de impressão 3D'),('prototipo-mecanico','Protótipo mecânico','Exploração de geometrias funcionais e componentes técnicos. Conteúdo de demonstração.','22222222-2222-4222-8222-222222222222','["example:turbine"]',true,true,true,1,''),('arquitetura-organica','Arquitetura orgânica','Um estudo de volumes, passagens e formas orgânicas à escala. Conteúdo de demonstração.','33333333-3333-4333-8333-333333333333','["example:architecture"]',true,true,true,2,''),('colecao-forma','Coleção Forma','Exploração de superfícies e texturas paramétricas. Conteúdo de demonstração.','11111111-1111-4111-8111-111111111111','["example:spiral"]',true,true,true,3,''),('componentes-funcionais','Componentes funcionais','Estudo de peças para prototipagem. Conteúdo de demonstração.','22222222-2222-4222-8222-222222222222','["example:turbine"]',true,true,true,4,''),('maqueta-conceptual','Maqueta conceptual','Uma exploração espacial em três dimensões. Conteúdo de demonstração.','33333333-3333-4333-8333-333333333333','["example:architecture"]',true,true,true,5,'');
INSERT INTO public.services(name,description,details,published,example,position) VALUES ('Modelação 3D','Da primeira ideia a um modelo com todos os detalhes.','Conteúdo de exemplo. O serviço será confirmado e descrito pela SDS3D.',true,true,0),('Impressão 3D','Do digital ao físico. Formas que podes tocar.','Conteúdo de exemplo. Materiais e tecnologias a confirmar pela SDS3D.',true,true,1),('Prototipagem','Explorar, testar e aperfeiçoar antes de avançar.','Conteúdo de exemplo. Aplicações a confirmar.',true,true,2),('Projetos personalizados','Uma abordagem feita à medida da tua ideia.','Conteúdo de exemplo. Serviço a confirmar pela SDS3D.',true,true,3);
INSERT INTO public.site_settings(id,content) VALUES ('main','{"hero_title":"As tuas ideias\nganham forma.","hero_subtitle":"Modelação 3D, criatividade e soluções personalizadas.","about":"A SDS3D é um espaço para transformar ideias em formas. Entre a criatividade e a precisão técnica, cada projeto começa com uma nova possibilidade.","about_note":"Apresentação provisória — a substituir pela história real da SDS3D.","email":"","whatsapp":"","instagram":"","facebook":"","location":"","footer":"Ideias com forma. Projetos com identidade.","primary_color":"#d6f36b"}');